        do
        {
            float t = (float)i * 0.016129032f;
            float angle = t * 12.566371f;
            float folded = (t - 0.5f) < 0.0f ? -(t - 0.5f) : (t - 0.5f);
            float folded_copy = (t - 0.5f) < 0.0f ? -(t - 0.5f) : (t - 0.5f);

