                ->transform.basis_right.Cross(
                    ((PathTemplateSample *)((char *)primary_samples + i) - 1)
                        ->transform.basis_up,
                    ((PathTemplateSample *)((char *)primary_samples + i) - 1)
                        ->transform.basis_forward);

